  recoverInterrupted(): void {
    this.stmt(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`).run(timestamp());
  }

  setProgress(id: string, completed: number): void {
    this.stmt(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(completed, timestamp(), id);
  }

  completeJob(id: string, output: string): void {
    this.stmt(
      `UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(output, timestamp(), id);
  }

  failJob(id: string, error: string): void {
    this.stmt(`UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'`).run(
      error,
      timestamp(),
      id,
    );
  }

  requeueJob(id: string, runAfterMs: number): void {
    this.stmt(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
      runAfterMs,
      timestamp(),
      id,
    );
  }

