      `UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
    ).run(timestamp(), id);
  }

  heartbeat(nowMs: number = Date.now()): void {
    this.stmt(`INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`).run(nowMs);
  }

  clearHeartbeat(): void {
    this.stmt(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
  }

  isWorkerUp(nowMs: number = Date.now()): boolean {
    const row = this.one<{ at: number }>(`SELECT at FROM heartbeats WHERE name = 'worker'`);
    return row !== undefined && nowMs - row.at <= HEARTBEAT_TTL_MS;
  }
}

